from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_fresh_v5_v439.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p): compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    req=["alliance_autonomous_student_v438.py","alliance_truth_integrity_v426.py",
         "alliance_automation_truth_escalator_v421.py","alliance_automation_closure_v422.py",
         "alliance_automation_grammar_rescue_v423.py","alliance_acquisition_intent_closure_v425.py",
         "alliance_autonomous_student_v430.py",REG]
    miss=[x for x in req if not (r/x).exists()]
    if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))

    v438=(r/"alliance_autonomous_student_v438.py").read_text(encoding="utf-8")
    for marker in [
        'VERSION = "4.3.8-ALLIANCE-STUDENT-DEMAND-OBJECT-CLOSURE"',
        "V438_TRAINING_PASS_READY_FOR_FRESH_V5_FREEZER",
    ]:
        if marker not in v438:
            raise SystemExit("4.3.8 baseline mismatch; refusing V5 freeze: "+marker)

    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")
    chk(r/MODULE)

    reg=r/REG; old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v439-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)

    marker="# FOUNDATION 4.3.9 - Fresh V5 Frozen Certification"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0: raise SystemExit("Registrar return not found.")
        block=r"""
    # FOUNDATION 4.3.9 - Fresh V5 Frozen Certification
    # Locks Student 4.3.8 before truth; no student tuning after freeze.
    try:
        if _route_exists(app, "/api/property-brain/fresh-v5-v439/status"):
            result["fresh_v5_v439"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/fresh-v5-v439","error":None}
        else:
            import alliance_fresh_v5_v439 as v439
            result["fresh_v5_v439"] = {**v439.register(core), "error": None}
    except Exception as exc:
        result["fresh_v5_v439"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")
    chk(reg)

    print("Alliance Fresh V5 4.3.9 installed")
    print("Locked student: 4.3.8")
    print("Fresh V5 freeze + independent automated examiner enabled")
    print("Student tuning after freeze: prohibited")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/fresh-v5-v439")
    print("Backup:",bak)

if __name__=="__main__": main()
